import { debounce } from 'lodash-es';
import type { Hooks, TableInstance } from 'react-table';
import { ColumnInstance } from 'react-table';

const DEBOUNCE_TIME_MS = 300;

/**
 * Clean up the table instance's copy of the debounced columns' functions in case
 * they were removed from the Datatable.
 * @param instanceDebouncedColumnFunctions - instance columns' debounced function record
 * @param instanceColumnIds - column ids currently on the Datatable
 * @returns - record with keys matching the column ids passed in
 */
export const cleanUpColumns = (
  instanceDebouncedColumnFunctions: Record<string, () => void>,
  instanceColumnIds: string[],
): Record<string, () => void> => {
  const cleanRecord = {};

  if (
    instanceDebouncedColumnFunctions === undefined ||
    instanceColumnIds === undefined
  ) {
    return cleanRecord;
  }

  Object.keys(instanceDebouncedColumnFunctions).forEach((key) => {
    if (instanceColumnIds.includes(key)) {
      cleanRecord[key] = instanceDebouncedColumnFunctions[key];
    }
  });

  return cleanRecord;
};
/** Uses the table instance to manipulate and extend the table behavior adding a debounce
 * on the built-in sort toggling feature. This limits the number of updates the table has to
 * go through if the user attempts to sort the same column multiple times in an extremely short amount
 * of time.
 */
function useInstance(
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  instance: TableInstance<any>,
) {
  const { flatHeaders, disableSortBy } = instance;

  // Instantiate the record if it is undefined
  if (instance.columnsToggleSortByDebounced === undefined) {
    instance.columnsToggleSortByDebounced = {};
  }

  // Clean up the column entries in the debounced function list
  instance.columnsToggleSortByDebounced = cleanUpColumns(
    instance.columnsToggleSortByDebounced,
    flatHeaders.map((col) => col.id),
  );

  if (!disableSortBy) {
    // Loop over all columns adding the debounced version of the column's toggleSortBy
    flatHeaders.forEach((column: ColumnInstance) => {
      const originalToggleSortBy = column.toggleSortBy;

      if (instance.columnsToggleSortByDebounced[column.id] === undefined) {
        instance.columnsToggleSortByDebounced[column.id] = debounce(
          (descending?: boolean, multi?: boolean) => {
            originalToggleSortBy(descending, multi);
          },
          DEBOUNCE_TIME_MS,
          { leading: true, trailing: false },
        );
      }
      // Debounce the built-in toggleSortBy for column
      column.toggleSortBy = instance.columnsToggleSortByDebounced[column.id];
    });
  }
}

/**
 * Hook for setting a debounce on toggling of sort on a column.
 */
export function useDebounceSort(
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  hooks: Hooks<any>,
): void {
  hooks.useInstance.push(useInstance);
}

useDebounceSort.pluginName = 'useDebounceSort';
